import {stationLayout,objectLabel} from './station-layouts.js';
import {stationObject} from './station-art.js';
const e=(s='')=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plant=(x,y,s=1)=>`<g transform="translate(${x-34*s} ${y-57*s}) scale(${.34*s})">${stationObject('plant')}</g>`;
function background(level){
 const base=['#b7dfa7','#c6dcef','#b1dda4','#c9dfb8','#c4d1df','#bbe5ed'][level-1];
 let s=`<rect width="1050" height="850" fill="${base}"/><rect x="15" y="15" width="1020" height="820" rx="25" fill="none" stroke="#102a56" stroke-opacity=".12" stroke-width="5"/>`;
 if(level===1)s+=`<path d="M190 105H820V600H190Z" fill="#eed5a0"/><path d="M200 110H812M200 590H812" stroke="#d5b57b" stroke-width="12"/>${[210,300,390,480].map(y=>`<path d="M200 ${y}H812" stroke="#fff2d5" stroke-width="2"/>`).join('')}${plant(245,180,1.2)}${plant(790,200,1.2)}`;
 if(level===2)s+=`<path d="M25 30H1025V112H25Z" fill="#2761b7"/><path d="M25 112H1025" stroke="#ffc928" stroke-width="8"/>${[130,350,570,790].map(x=>`<rect x="${x}" y="48" width="125" height="48" rx="8" fill="#8dd9f2" stroke="#102a56" stroke-width="4"/>`).join('')}<path d="M35 446H1015M35 640H1015M450 130V815M650 130V815" stroke="#aec6dd" stroke-width="2"/>${plant(65,227,1.1)}${plant(975,750,1.1)}`;
 if(level===3)s+=`<rect x="235" y="255" width="555" height="360" rx="140" fill="#65bd75" stroke="#e2edba" stroke-width="15"/><ellipse cx="535" cy="436" rx="82" ry="61" fill="#f4e4a5"/><ellipse cx="535" cy="431" rx="62" ry="43" fill="#63cde2" stroke="white" stroke-width="7"/>${plant(505,370,1.1)}${plant(610,445,1.1)}<path d="M250 710v30" stroke="#ffb72d" stroke-width="11"/><path d="M250 720h50" stroke="#102a56" stroke-width="10"/>`;
 if(level===4)s+=`<path d="M30 40H325V410H30Z" fill="#99c28f"/><path d="M40 57H319M41 57V405" stroke="#5a8b7b" stroke-width="8" stroke-dasharray="13 10"/>${plant(115,235,1.6)}${plant(210,335,1.5)}<path d="M720 615H1005V785H720Z" fill="#a4ce98"/>${plant(815,720,1.5)}${plant(959,695,1.3)}`;
 if(level===5)s+=`<path d="M25 25H1025V122H25Z" fill="#244b79"/>${[110,360,610,860].map(x=>`<path d="M${x} 40h115v56H${x}" fill="#8ad7ed" stroke="#102a56" stroke-width="5"/>`).join('')}<path d="M42 145H1010M42 743H1010" stroke="#eef5f9" stroke-width="7"/>${[130,350,570,790].map(x=>`<path d="M${x} 151V338M${x} 531V731" stroke="#a4b6c9" stroke-width="3"/>`).join('')}<path d="M30 393H1020M30 457H1020" stroke="#ffc928" stroke-width="5" stroke-dasharray="12 8"/>`;
 if(level===6)s+=`<path d="M25 30H450V340H25Z" fill="#9bccab"/><path d="M45 280H425V315H45Z" fill="#54768b"/>${[70,155,240,325].map(x=>`<path d="M${x} 292h40" stroke="white" stroke-width="4"/>`).join('')}<path d="M43 79q25-26 50-5 24-38 59-7 50-5 42 34H45Z" fill="#fff" opacity=".8"/><path d="M370 122v120" stroke="#102a56" stroke-width="6"/><path d="M370 125l-85 14 3 36 82-15Z" fill="#ff9d58" stroke="#102a56" stroke-width="3"/><path d="M340 132v34m-26-30v35" stroke="white" stroke-width="10"/><rect x="605" y="390" width="277" height="342" rx="80" fill="#92c0ca" stroke="#e2f6dc" stroke-width="5"/>`;
 return s;
}
export function interiorMap({maze:m,position:p,solved=[],route=[],avatar='boy',level=1,camera=false,interactive=true}){
 const l=stationLayout(level),W=m.width*50,H=m.height*50,span=400;
 const cameraX=Math.max(0,Math.min(W-span,p.x*50+25-span/2)),cameraY=Math.max(0,Math.min(H-span,p.y*50+25-span/2));
 const view=camera?`${cameraX} ${cameraY} ${span} ${span}`:`0 0 ${W} ${H}`;
 const d=m.path.map((q,i)=>`${i?'L':'M'}${q.x*50+25} ${q.y*50+25}`).join('');
 let s=`<svg xmlns="http://www.w3.org/2000/svg" class="maze-svg road-maze station-maze ${camera?'following':''}" id="maze" viewBox="${view}" role="group" aria-label="${e(l.caption)}. Lokasi kamu: lajur ${p.x}, baris ${p.y}." data-x="${p.x}" data-y="${p.y}" data-station="${level}">${background(level)}<g fill="none" stroke-linejoin="round" stroke-linecap="round"><path d="${d}" stroke="#fff4d9" stroke-width="76"/><path d="${d}" stroke="${level===2?'#6086b6':level===1?'#b89364':'#405368'}" stroke-width="59"/><path d="${d}" stroke="${level===1?'#fff1c9':'#ffe281'}" stroke-width="3" stroke-dasharray="10 15"/></g>`;
 if(level===3)s+=`<g stroke="white" stroke-width="7">${[-20,-10,0,10,20].map(dy=>`<path d="M102 ${475+dy}h46"/>`).join('')}</g>`;
 const drawObject=(o,i,decor=false)=>{const [kind,label,x,y,w,h]=o;const cx=(x+w/2)*50,box=objectLabel(o);return `<g class="station-object" data-object="${kind}" data-bounds="${[x,y,w,h].join(',')}" ${!decor&&interactive?`role="button" tabindex="0" data-hand="true" data-station-target="${i}" aria-label="Cabaran ${i+1}: ${e(label)}"`:''}><svg x="${x*50}" y="${y*50}" width="${w*50}" height="${h*50}" viewBox="0 0 200 180" preserveAspectRatio="xMidYMid meet" overflow="visible" class="station-object-art">${stationObject(kind)}</svg><rect x="${box.x}" y="${box.y}" width="${box.width}" height="${box.height}" rx="12" fill="#102a56"/>${box.lines.map((line,j)=>`<text x="${cx}" y="${box.y+21+j*18}" text-anchor="middle" class="station-label">${e(line)}</text>`).join('')}</g>`;};
 l.decor.forEach(o=>s+=drawObject(o,0,true));l.objects.forEach((o,i)=>s+=drawObject(o,i));
 for(const q of route)s+=`<circle class="route" cx="${q.x*50+25}" cy="${q.y*50+25}" r="7"/>`;
 const marker=(point,label,color)=>`<g class="station-${label==='MULA'?'start':'end'}"><circle cx="${point.x*50+25}" cy="${point.y*50+25}" r="26" fill="${color}" stroke="white" stroke-width="4"/><text x="${point.x*50+25}" y="${point.y*50+30}" text-anchor="middle" fill="white" font-size="12" font-weight="900">${label==='MULA'?'':label}</text></g>`;
 s+=marker(m.start,'MULA','#0c805c')+marker(m.end,'TAMAT','#174beb');
 const startLeft=m.path[1].x<m.start.x,sx=m.start.x*50+25-(startLeft?0:72),sy=m.start.y*50+25-(startLeft?78:0);
 s+=`<g class="station-start"><rect x="${sx-31}" y="${sy-14}" width="62" height="28" rx="10" fill="#0c805c"/><text x="${sx}" y="${sy+6}" font-size="17" font-weight="900" text-anchor="middle">MULA</text></g>`;

 m.points.forEach(({challenge:c,gate:g},i)=>{const done=solved.includes(i),vertical=g.x===c.x;const available=m.points.slice(0,i).every((_,j)=>solved.includes(j));
  s+=`<g class="${done?'open-gate':'gate'}" transform="translate(${g.x*50+25} ${g.y*50+25}) rotate(${vertical?0:90})"><rect x="-26" y="-6" width="52" height="12" rx="4" fill="${done?'#21a66b':'#ffb52d'}" stroke="#102a56" stroke-width="2"/>${!done?'<path d="M-21-4l8 8M-5-4l8 8M11-4l8 8" stroke="white" stroke-width="4"/>':''}</g><g class="station-stop ${done?'done':available?'available':'waiting'}" ${interactive?`role="button" tabindex="0" data-hand="true" data-station-target="${i}" aria-label="Cabaran ${i+1}: ${e(l.objects[i][1])}${done?', selesai':''}"`:''} data-index="${i}" transform="translate(${c.x*50+25} ${c.y*50+25})"><circle r="29" fill="#102a56"/><circle r="25" fill="${done?'#12834e':'#174beb'}" stroke="#ffc928" stroke-width="5"/><text y="8" text-anchor="middle" fill="white" font-size="24" font-weight="900">${done?'✓':i+1}</text></g>`;
 });
 s+=`<g class="player" pointer-events="none" transform="translate(${p.x*50},${p.y*50})"><ellipse cx="25" cy="45" rx="23" ry="8" fill="#3de3ee" stroke="white" stroke-width="3"/><image href="assets/v2/police-${['boy','girl','hijab'].includes(avatar)?avatar:'boy'}.png" x="-8" y="-29" width="66" height="80" preserveAspectRatio="xMidYMid meet"/></g></svg>`;
 if(camera)s+=`<div class="station-overview"><div><strong>Peta kecil</strong>Kedudukan kamu dalam stesen</div><svg class="maze-minimap station-minimap" viewBox="0 0 ${W} ${H}" aria-label="Peta kecil laluan stesen" role="img"><rect width="${W}" height="${H}" fill="#e8f4f3"/><path d="${d}" fill="none" stroke="#35557c" stroke-width="36" stroke-linejoin="round"/><rect x="${cameraX}" y="${cameraY}" width="${span}" height="${span}" fill="#174beb16" stroke="#174beb" stroke-width="8"/><circle cx="${p.x*50+25}" cy="${p.y*50+25}" r="27" fill="#174beb" stroke="#ffc928" stroke-width="12"/></svg></div>`;
 return s;
}
